def comps(g,val):
    H,W=len(g),len(g[0]); seen=set(); out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]==val and (r,c) not in seen:
                q=[(r,c)]; seen.add((r,c)); cells=[]
                while q:
                    a,b=q.pop(); cells.append((a,b))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+dx,b+dy
                        if 0<=na<H and 0<=nb<W and g[na][nb]==val and (na,nb) not in seen:
                            seen.add((na,nb)); q.append((na,nb))
                out.append(cells)
    return out
